/**
 * strip-types.js — Strips TypeScript type annotations from runner.ts
 * to produce valid JavaScript runnable under Node.js v18 as ESM (.mjs).
 *
 * Usage: node strip-types.js <input.ts> <output.mjs>
 *
 * Strategy: targeted transforms only for patterns actually used in runner.ts.
 * We do NOT do generic "strip all : Type" — that would break object literals.
 */

const fs = require("fs");

const inputPath = process.argv[2];
const outputPath = process.argv[3];

if (!inputPath || !outputPath) {
  process.stderr.write("Usage: node strip-types.js <input.ts> <output.mjs>\n");
  process.exit(1);
}

